<?php $job=row('SELECT * FROM crawl_jobs WHERE website_id=? ORDER BY id DESC LIMIT 1',[$wid]);$a=row('SELECT * FROM seo_audits WHERE website_id=? ORDER BY id DESC LIMIT 1',[$wid]);?><div class="card"><div class="card-header"><div><h3>Technical SEO audit</h3><p class="small"><?=e($w['domain'])?></p></div><button class="button" data-action="crawl" data-website-id="<?=$wid?>">ϟ Run a fresh audit</button></div><?php if($job):?><div class="alert" <?=in_array($job['status'],['queued','running'])?'data-crawl-progress="'.$wid.'" data-crawl-can-run="'.((is_admin() || (int)$w['user_id']===(int)$user['id'])?'1':'0').'"':''?>>Crawl #<?=$job['id']?> · <?=e($job['status'])?> · <?=$job['processed']?> / <?=$job['max_pages']?> pages<?php if($job['error']):?> · <?=e($job['error'])?><?php endif;?></div><?php endif; if($a):?><p>SEO Health Score: <strong><?=$a['score']?>/100</strong>. Internal diagnostic score using configurable technical, on-page, content, performance and linking weights.</p><?php $severity=(string)($_GET['severity']??'');$params=[$a['id']];$sql='SELECT * FROM seo_issues WHERE audit_id=?';if(in_array($severity,['critical','high','medium','low','opportunity'])){$sql.=' AND severity=?';$params[]=$severity;}$p=max(1,min(10000,(int)($_GET['page']??1)));$issues=rows($sql.' ORDER BY FIELD(severity,"critical","high","medium","low","opportunity"),id LIMIT 30 OFFSET '.(($p-1)*30),$params);?><nav class="tabs"><?php foreach([''=>'All issues','critical'=>'Critical','high'=>'High','medium'=>'Medium','low'=>'Low','opportunity'=>'Opportunities'] as $k=>$v):?><a class="<?=$severity===$k?'active':''?>" href="?website_id=<?=$wid?>&severity=<?=e($k)?>"><?=e($v)?></a><?php endforeach;?></nav><?php foreach($issues as $issue):?><article class="issue"><div class="row between"><div class="row"><span class="badge <?=e($issue['severity'])?>"><?=e($issue['severity'])?></span><h3><?=e($issue['title'])?></h3></div><span class="badge"><?=e($issue['status'])?></span></div><small><?=e($issue['url'])?></small><p><strong>Why it matters:</strong> <?=e($issue['explanation'])?></p><p><strong>Recommendation:</strong> <?=e($issue['recommendation'])?></p><div class="row"><button class="button secondary small-button" data-action="issue-task" data-id="<?=$issue['id']?>" data-website-id="<?=$wid?>">+ Create task</button><button class="text-button" data-action="issue-status" data-id="<?=$issue['id']?>" data-website-id="<?=$wid?>" data-status="resolved">Mark resolved</button><button class="text-button" data-action="issue-status" data-id="<?=$issue['id']?>" data-website-id="<?=$wid?>" data-status="ignored">Ignore</button></div></article><?php endforeach;if(!$issues)empty_state('No issues in this view','Try another severity filter.');?><nav class="pagination"><?php if($p>1):?><a href="?website_id=<?=$wid?>&severity=<?=e($severity)?>&page=<?=$p-1?>">← Previous</a><?php endif;if(count($issues)===30):?><a href="?website_id=<?=$wid?>&severity=<?=e($severity)?>&page=<?=$p+1?>">Next →</a><?php endif;?></nav><?php else:empty_state('Your first insight is one crawl away.','Run an audit and keep this page open while we check your site and build your issue list.');endif;?></div><?php if($job):?><div class="card stack"><h3>Crawl failures & blocked URLs</h3><?php table(['url'=>'URL','status'=>'Status','error'=>'Details'],rows("SELECT url,status,error FROM crawl_urls WHERE job_id=? AND status IN ('failed','blocked') LIMIT 50",[$job['id']]));?></div><?php endif;?>
